describe('Search Bar Mobile Expansion on Focus', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should expand search bar on focus on mobile viewport', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('have.attr', 'type', 'text');
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-input"]').should('have.attr', 'aria-expanded', 'true');
    cy.get('[data-testid="search-input"]').should('have.class', 'expanded');
    cy.get('[data-testid="search-input"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="search-input"]').should('have.css', 'height', '50px');
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('contain', 'Search...');
  });

  it('should collapse search bar when focus is lost on mobile viewport', () => {
    cy.viewport('iphone-12');
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-input"]').should('have.class', 'expanded');
    cy.get('[data-testid="search-input"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="search-input"]').type('test query');
    cy.get('[data-testid="search-input"]').blur();
    cy.get('[data-testid="search-input"]').should('not.have.class', 'expanded');
    cy.get('[data-testid="search-input"]').should('have.css', 'width', 'auto');
    cy.get('[data-testid="search-input"]').should('have.css', 'height', '40px');
    cy.get('[data-testid="search-input"]').should('contain', 'test query');
  });
});
